const fs = require('fs');
const tokens = fs.readFileSync(0, 'utf8').split(/\s+/).filter(Boolean);

let p = 0;
const n = parseInt(tokens[p++], 10);

const totals = new Map();   // amigo -> soma dos tempos de resposta
const pending = new Map();  // amigo -> timestamp do R pendente (sem resposta)

let t = 0;            // relógio (offset irrelevante, só diferenças importam)
let nextDelta = null; // delta definido por registro T entre dois eventos

for (let i = 0; i < n; i++) {
  const type = tokens[p++];
  const x = parseInt(tokens[p++], 10);

  if (type === 'T') {
    // X segundos entre o evento anterior e o posterior (substitui o padrão de 1s)
    nextDelta = (nextDelta === null ? 0 : nextDelta) + x;
  } else {
    // ocorre um evento: avança o relógio
    t += (nextDelta === null ? 1 : nextDelta);
    nextDelta = null;

    if (type === 'R') {
      pending.set(x, t);
      if (!totals.has(x)) totals.set(x, 0);
    } else { // 'E': responde à mensagem pendente desse amigo (a única pendente)
      if (pending.has(x)) {
        totals.set(x, totals.get(x) + (t - pending.get(x)));
        pending.delete(x);
      }
    }
  }
}

const friends = Array.from(totals.keys()).sort((a, b) => a - b);
const out = friends.map(f => `${f} ${pending.has(f) ? -1 : totals.get(f)}`);
process.stdout.write(out.join('\n') + (out.length ? '\n' : ''));
